(async () => {
  const a = [...document.querySelectorAll('a')].find(x => (x.getAttribute('href')||'').endsWith('#quote'));
  if (!a) return {error: 'no #quote link'};
  a.click();
  await new Promise(r => setTimeout(r, 400));
  const m = document.getElementById('gquote');
  return {href: a.getAttribute('href'), hasAttr: a.hasAttribute('data-quote-open'), opened: m ? !m.hidden : null,
          img: m ? m.querySelector('.gquote__img').getAttribute('src') : ''};
})()
